from __future__ import annotations
import json,sys
from dataclasses import fields,replace
from pathlib import Path
from typing import Any
sys.path.insert(0,str(Path.cwd()))
import torch
from benchmarks.cases import CASES
from pinnstorch.api import Coordinates,Equation,TensorFields
from pinnstorch.runner.factory import SolverFactory
from pinnstorch.runner.problem import load_problem
from pinnstorch.runner.settings import TaskSettings
from pinnstorch.training.robin_box import BoxRobinInitial,BoundBoxRobinInitial
from pinnstorch.training.robin_initial import IntervalRobinInitial,BoundRobinInitial

class StaticBoxBackground(BoxRobinInitial):
 def background(self,spatial:list[torch.Tensor],time:torch.Tensor)->TensorFields:
  return self.initial(spatial,torch.full_like(time,self.time_interval[0]))

class StaticIntervalBackground(IntervalRobinInitial):
 def background(self,x:torch.Tensor,time:torch.Tensor)->TensorFields:
  return self.initial([x],torch.full_like(time,self.time_interval[0]))

def constant_initial(c:Coordinates)->TensorFields:
 return {'u':torch.ones_like(c.t)}

def flux_initial(c:Coordinates)->TensorFields:
 value=torch.ones_like(c.t)
 for x in c.spatial.values():value=value+x
 return {'u':value}

def static_transform(settings:TaskSettings,bound:Any)->Any:
 if any(b.value_function is not None for b in settings.boundaries):
  raise ValueError('Static numeric data required; callbacks cannot be inferred constant')
 if not isinstance(bound,(BoundRobinInitial,BoundBoxRobinInitial)):
  raise ValueError('Exact Robin/Neumann transform required')
 recipe=bound.recipe
 kwargs={f.name:getattr(recipe,f.name) for f in fields(recipe) if f.init}
 cls=StaticBoxBackground if isinstance(recipe,BoxRobinInitial) else StaticIntervalBackground
 return cls(**kwargs).bind(bound.network)

if __name__=='__main__':
 torch.set_num_threads(1);torch.manual_seed(19)
 root=Path('numerical-reports/static-background-cpu-probe-001');root.mkdir(parents=True,exist_ok=False)
 rows=[]
 for dimensions in (1,2,3):
  for condition in ('neumann_zero','neumann_flux','robin_constant'):
   case=CASES[f'heat_neumann_polynomial{dimensions}d'];problem=load_problem(case.source)
   for execution in ('eager','robin_grouped'):
    config=case.config('cpu',2,19);config['network']['hidden_layers']=[4,4]
    config['training'].update(constraints='hard_initial_robin',hard_execution=execution,backward='all')
    if condition=='neumann_flux':
     problem=replace(problem,initial=flux_initial)
     config['boundaries']=[dict(kind='neumann',field='u',axis=axis,side=side,value=value) for axis in 'xyz'[:dimensions] for side,value in (('lower',-1),('upper',1))]
    elif condition=='robin_constant':
     problem=replace(problem,initial=constant_initial)
     config['boundaries']=[dict(kind='robin',field='u',axis=axis,alpha=2,beta=1,value=2) for axis in 'xyz'[:dimensions]]
    factory=SolverFactory(TaskSettings.read(config),problem,root,case.source.parent);model=factory.build(True).model
    original=model.output_fn;shortcut=static_transform(factory.settings,original)
    for dtype in (torch.float32,torch.float64):
     model=model.to(dtype=dtype)
     raw=torch.rand((5,dimensions+1),dtype=dtype);raw[:,-1]*=.5
     results=[]
     for transform in (original,shortcut):
      model.output_fn=transform
      columns=[raw[:,i:i+1].clone().requires_grad_() for i in range(dimensions+1)]
      output=dict(model(columns[:-1],columns[-1]));c=Coordinates(dict(zip('xyz',columns[:-1])),columns[-1]);e=Equation(output,c)
      values=[output['u'],e.dt('u'),e.laplacian('u')]
      residual=factory.adapter.residuals(output,*columns)['heat'];values.append(residual)
      gradients=torch.autograd.grad(residual.square().mean(),tuple(model.parameters()))
      results.append([v.detach().clone() for v in (*values,*gradients)])
     tolerance=1e-5 if dtype==torch.float32 else 1e-12
     for a,b in zip(*results):torch.testing.assert_close(a,b,rtol=tolerance,atol=tolerance)
     rows.append(dict(dimensions=dimensions,condition=condition,execution=execution,dtype=str(dtype),all_tensors_exact=all(torch.equal(a,b) for a,b in zip(*results)),max_abs_difference=max(float((a-b).abs().max()) for a,b in zip(*results))))
 case=CASES['heat_neumann2d'];p=load_problem(case.source);cfg=case.config('cpu',2,19);cfg['training']['constraints']='hard_initial_robin'
 factory=SolverFactory(TaskSettings.read(cfg),p,root,case.source.parent);bound=factory.build(True).model.output_fn
 try:static_transform(factory.settings,bound)
 except ValueError:callback_rejected=True
 else:raise AssertionError('Dynamic callback was accepted')
 report=dict(contract=1,device='cpu',torch=torch.__version__,comparisons=rows,dynamic_callback_rejected=callback_rejected,prototype_source=Path(__file__).read_text(),limitations='Experimental low-level background override only, not integrated into production. Frozen small random networks, no training, no CUDA timing. Explicit numeric constant operator data; physical field/time derivative/Laplacian/PDE residual/parameter gradients compared. Does not cover arbitrary callbacks or time-varying operators.')
 Path('docs/experiments/2026-10-16-static-background-cpu.json').write_text(json.dumps(report,indent=2,allow_nan=False))
 print(json.dumps({k:v for k,v in report.items() if k!='prototype_source'},indent=2))
